css.morsel:
/* ============================================================
   MORSEL — design tokens & shared styles
   Type scale (iOS pt): 34 display / 28 title / 22 heading /
   17 body / 15 secondary / 13 caption / 11 micro
   Spacing: 4pt base — 4 / 8 / 12 / 16 / 20 / 24 / 32
   ============================================================ */

.morsel-app {
  /* Direction A — "Toast": cream + terracotta + Lora serif */
  --paper: #F7F1E6;
  --surface: #FFFCF5;
  --sunken: #EFE6D6;
  --ink: #26190E;
  --ink-2: rgba(38, 25, 14, 0.72);
  --ink-3: rgba(38, 25, 14, 0.62);
  --line: rgba(38, 25, 14, 0.10);
  --accent: #B2401F;
  --accent-ink: #FFF6EC;
  --glass: rgba(28, 18, 10, 0.66);
  --glass-text: #FFF9F0;
  --r: 22px;
  --font-display: "Lora", Georgia, serif;
  --font-ui: "Hanken Grotesk", -apple-system, "SF Pro Text", sans-serif;
  --display-weight: 600;
  --shadow-card: 0 1px 2px rgba(38,25,14,.05), 0 8px 28px rgba(38,25,14,.10);
  --shadow-float: 0 2px 6px rgba(38,25,14,.12), 0 14px 40px rgba(38,25,14,.22);
  --ts: 1; /* v3: Dynamic Type multiplier (100% = 1) */

  font-family: var(--font-ui);
  color: var(--ink);
  background: var(--paper);
  width: 100%; height: 100%;
  display: flex; flex-direction: column;
  position: relative; overflow: hidden;
  -webkit-font-smoothing: antialiased;
}

/* Direction B — "Saffron": all-grotesque, golden accent, squarer, denser */
.morsel-app[data-dir="saffron"] {
  --paper: #FBF8F1;
  --surface: #FFFFFF;
  --sunken: #F1ECDF;
  --ink: #1F1A12;
  --ink-2: rgba(31, 26, 18, 0.72);
  --ink-3: rgba(31, 26, 18, 0.62);
  --line: rgba(31, 26, 18, 0.10);
  --accent: #C97C1B;
  --accent-ink: #FFF9EE;
  --r: 14px;
  --font-display: "Hanken Grotesk", -apple-system, sans-serif;
  --display-weight: 800;
}

/* Direction C — "Charred": after dark, photos glow */
.morsel-app[data-dir="charred"] {
  --paper: #171210;
  --surface: #221B16;
  --sunken: #2B221C;
  --ink: #F4ECDF;
  --ink-2: rgba(244, 236, 223, 0.76);
  --ink-3: rgba(244, 236, 223, 0.62);
  --line: rgba(244, 236, 223, 0.12);
  --accent: #E2603A;
  --accent-ink: #FFF6EC;
  --glass: rgba(10, 6, 3, 0.66);
  --shadow-card: 0 1px 2px rgba(0,0,0,.3), 0 8px 28px rgba(0,0,0,.4);
  --shadow-float: 0 2px 6px rgba(0,0,0,.4), 0 14px 40px rgba(0,0,0,.55);
}

.morsel-app * { box-sizing: border-box; margin: 0; }
.morsel-app img { display: block; }
.morsel-app :where(button) {
  font-family: var(--font-ui); border: none; background: none;
  color: inherit; cursor: pointer; padding: 0; text-align: inherit;
}

/* ---- type helpers (scaled by --ts for Dynamic Type) ---- */
.m-display { font-family: var(--font-display); font-weight: var(--display-weight); font-size: calc(34px * var(--ts)); line-height: 1.05; letter-spacing: -0.01em; }
.m-title   { font-family: var(--font-display); font-weight: var(--display-weight); font-size: calc(28px * var(--ts)); line-height: 1.1; letter-spacing: -0.01em; }
.m-heading { font-family: var(--font-display); font-weight: var(--display-weight); font-size: calc(22px * var(--ts)); line-height: 1.15; }
.m-body    { font-size: calc(17px * var(--ts)); line-height: 1.45; }
.m-second  { font-size: calc(15px * var(--ts)); line-height: 1.4; }
.m-caption { font-size: calc(13px * var(--ts)); line-height: 1.35; }
.m-micro   { font-size: calc(11px * var(--ts)); line-height: 1.3; font-weight: 600; letter-spacing: 0.08em; text-transform: uppercase; }

/* ---- screen scaffold ---- */
.m-screen { flex: 1; min-height: 0; display: flex; flex-direction: column; overflow: hidden; position: relative; }
.m-scroll { flex: 1; min-height: 0; overflow-y: auto; overscroll-behavior: contain; scrollbar-width: none; }
.m-scroll::-webkit-scrollbar { display: none; }

/* ---- glass chrome over photos ---- */
.m-glass {
  display: inline-flex; align-items: center; gap: 6px;
  background: var(--glass); color: var(--glass-text);
  backdrop-filter: blur(14px) saturate(1.3); -webkit-backdrop-filter: blur(14px) saturate(1.3);
  border: 1px solid rgba(255,255,255,0.14);
  border-radius: 999px; padding: 8px 14px;
  font-size: 13px; font-weight: 600; letter-spacing: 0.01em;
}
.m-glass-icon {
  width: 40px; height: 40px; padding: 0;
  justify-content: center; flex: none;
}

/* ---- buttons ---- */
.m-btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  border-radius: 999px; font-weight: 700; font-size: calc(16px * var(--ts));
  min-height: 52px; padding: 0 24px;
  transition: transform 0.15s ease, opacity 0.15s ease;
}
.m-btn:active { transform: scale(0.97); }
.m-btn-primary { background: var(--accent); color: var(--accent-ink); }
.m-btn-quiet { background: var(--sunken); color: var(--ink); }
.m-btn[disabled] { opacity: 0.35; pointer-events: none; }

/* ---- photo cards ---- */
.m-photo {
  position: relative; overflow: hidden; border-radius: var(--r);
  background: var(--sunken); width: 100%;
  transition: transform 0.18s ease;
}
.m-photo:active { transform: scale(0.97); }
.m-photo > img { width: 100%; height: 100%; object-fit: cover; position: absolute; inset: 0; }

/* gradient veil for text-on-photo */
.m-veil {
  position: absolute; inset: 0;
  background: linear-gradient(to top, rgba(12,7,3,0.72) 0%, rgba(12,7,3,0.18) 36%, rgba(12,7,3,0) 55%);
  pointer-events: none;
}

/* ---- tab bar ---- */
.m-tabbar {
  position: absolute; left: 50%; bottom: 26px; transform: translateX(-50%);
  display: flex; align-items: center; gap: 4px;
  background: var(--glass);
  backdrop-filter: blur(18px) saturate(1.4); -webkit-backdrop-filter: blur(18px) saturate(1.4);
  border: 1px solid rgba(255,255,255,0.16);
  border-radius: 999px; padding: 5px; z-index: 40;
  box-shadow: var(--shadow-float);
}
.m-tab {
  width: 52px; height: 46px; border-radius: 999px;
  display: flex; align-items: center; justify-content: center;
  color: rgba(255, 249, 240, 0.66);
  transition: background 0.18s ease, color 0.18s ease;
}
.m-tab[data-active="true"] { background: rgba(255, 249, 240, 0.94); color: #26190E; }

/* ---- chips ---- */
.m-chip {
  display: inline-flex; align-items: center; gap: 6px;
  border-radius: 999px; border: 1.5px solid var(--line);
  background: var(--surface); color: var(--ink);
  padding: 10px 18px; font-size: 15px; font-weight: 600;
  transition: all 0.15s ease; min-height: 44px;
}
.m-chip[data-on="true"] { background: var(--ink); color: var(--paper); border-color: var(--ink); }

/* ---- v3.2: labeled cards — photo first, identifiable before it is opened ---- */
.m-grid { display: grid; gap: 14px 10px; padding: 0 12px; align-items: start; }
.m-card { position: relative; min-width: 0; }
.m-card-open { display: block; width: 100%; text-align: left; border-radius: calc(var(--r) * 0.8); }
.m-card-photo {
  position: relative; aspect-ratio: 4 / 5; border-radius: calc(var(--r) * 0.8);
  overflow: hidden; background: var(--sunken); transition: transform 0.18s ease;
}
.m-card-open:active .m-card-photo { transform: scale(0.97); }
.m-card-photo > img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
.m-card-nophoto {
  position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center;
  gap: 4px; padding: 12px; text-align: center; color: var(--ink-2);
}
.m-card-text { padding: 8px 2px 0; display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.m-card-name { font-size: calc(15px * var(--ts)); font-weight: 700; line-height: 1.25; overflow-wrap: anywhere; }
.m-card-save { position: absolute; top: 8px; right: 8px; width: 36px; height: 36px; }
.m-statechip {
  display: inline-flex; align-items: center; gap: 4px; max-width: 100%;
  border-radius: 999px; padding: 5px 10px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
  font-size: calc(11.5px * var(--ts)); font-weight: 800;
}
.m-constraints { display: flex; flex-wrap: wrap; gap: 6px; align-items: center; padding: 0 16px 12px; }
.m-constraint { border-radius: 999px; padding: 6px 12px; font-weight: 700; min-height: 32px; }

/* ---- v3: keyboard focus, skeletons, warnings, banners ---- */
.morsel-app :where(button, input, a):focus-visible {
  outline: 2.5px solid var(--accent); outline-offset: 2px; border-radius: 8px;
}
@keyframes m-shimmer { from { background-position: 200% 0; } to { background-position: -200% 0; } }
.m-skel {
  background: linear-gradient(100deg, var(--sunken) 40%, rgba(255,255,255,0.45) 50%, var(--sunken) 60%);
  background-size: 200% 100%;
  animation: m-shimmer 1.4s linear infinite;
  border-radius: calc(var(--r) * 0.8);
}
.m-warnchip {
  position: absolute; top: 8px; left: 8px;
  display: inline-flex; align-items: center; gap: 5px;
  background: var(--accent); color: var(--accent-ink);
  border-radius: 999px; padding: 5px 10px;
  font-size: calc(11.5px * var(--ts)); font-weight: 800; white-space: nowrap;
}
.m-banner {
  display: flex; align-items: center; gap: 10px;
  margin: 12px 14px 0; padding: 11px 14px;
  border-radius: 16px; background: var(--sunken);
  border: 1px solid var(--line);
}

/* ---- shared-element zoom (tapped photo -> detail hero) ---- */
@keyframes m-zoom {
  from {
    left: var(--zx); top: var(--zy); width: var(--zw); height: var(--zh);
    border-radius: calc(var(--r) * 0.8); opacity: 1;
  }
  82% { opacity: 1; }
  to { left: 0; top: 0; width: 100%; height: 320px; border-radius: 0; opacity: 0; }
}
.m-zoom {
  position: absolute; overflow: hidden; pointer-events: none;
  left: 0; top: 0; width: 100%; height: 320px; opacity: 0;
  animation: m-zoom 0.5s cubic-bezier(0.2, 0.8, 0.2, 1) both;
}

/* ---- transitions: transform-only so paused/printed states stay visible ---- */
@keyframes m-rise { from { transform: translateY(14px); } to { transform: translateY(0); } }
@keyframes m-fade { from { transform: scale(0.99); } to { transform: scale(1); } }
.m-rise { animation: m-rise 0.35s cubic-bezier(0.2, 0.8, 0.2, 1) both; }
.m-fade { animation: m-fade 0.25s ease both; }
@media (prefers-reduced-motion: reduce) { .m-rise, .m-fade, .m-skel { animation: none; } .m-zoom { display: none; } }

/* Keep input and icon-button focus visible across every prototype surface. */
.morsel-app :focus-visible{outline:3px solid var(--ink);outline-offset:3px}
.morsel-app input:focus-visible,.morsel-app textarea:focus-visible{outline:3px solid var(--ink) !important;outline-offset:3px}

/* ============================================================
   Visual menu: restaurant picker, menu rows, photo strip, compare
   ============================================================ */
.m-topbar { display: flex; align-items: center; gap: 10px; padding: 8px 14px 6px; }
.m-iconbtn { width: 44px; height: 44px; border-radius: 999px; display: inline-flex; align-items: center; justify-content: center; background: var(--sunken); color: var(--ink); flex: none; }
.m-field { display: flex; align-items: center; gap: 10px; margin: 8px 16px 0; padding: 0 14px; min-height: 48px; border-radius: 14px; background: var(--surface); border: 1.5px solid var(--line); }
.m-field input { flex: 1; min-width: 0; border: none; background: none; font: inherit; font-size: calc(16px * var(--ts)); color: var(--ink); outline: none; }
.m-rest-list { display: flex; flex-direction: column; gap: 10px; padding: 12px 16px 24px; }
.m-rest-row { display: flex; align-items: center; gap: 12px; width: 100%; padding: 14px 16px; border-radius: 18px; background: var(--surface); border: 1.5px solid var(--line); text-align: left; }
.m-rest-row:active { transform: scale(0.985); }
.m-rest-row .m-rest-text { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 2px; }
.m-tag { display: inline-flex; align-items: center; gap: 5px; border-radius: 999px; padding: 5px 10px; font-size: calc(11.5px * var(--ts)); font-weight: 800; white-space: nowrap; max-width: 100%; overflow: hidden; text-overflow: ellipsis; background: var(--sunken); color: var(--ink-2); }
.m-tag[data-tone="on"] { background: var(--ink); color: var(--paper); }
.m-tag[data-tone="photo"] { background: var(--glass); color: var(--glass-text); backdrop-filter: blur(10px); -webkit-backdrop-filter: blur(10px); text-shadow: 0 1px 2px rgba(0,0,0,0.35); }

.m-seg { display: inline-flex; padding: 3px; border-radius: 999px; background: var(--sunken); }
.m-seg button { border-radius: 999px; padding: 8px 16px; font-size: calc(14px * var(--ts)); font-weight: 700; color: var(--ink-2); min-height: 38px; }
.m-seg button[aria-pressed="true"] { background: var(--surface); color: var(--ink); box-shadow: var(--shadow-card); }
.m-jump { display: flex; gap: 8px; overflow-x: auto; padding: 10px 16px 4px; scrollbar-width: none; }
.m-jump::-webkit-scrollbar { display: none; }
.m-jump .m-chip { padding: 8px 14px; min-height: 38px; font-size: calc(14px * var(--ts)); flex: none; }

.m-section { padding: 18px 16px 6px; }
.m-section h2 { font-family: var(--font-display); font-weight: var(--display-weight); font-size: calc(21px * var(--ts)); line-height: 1.15; }
.m-section .m-caption { margin-top: 2px; }
.m-rows { display: flex; flex-direction: column; gap: 10px; padding: 8px 16px 0; }
.m-row { position: relative; display: flex; gap: 12px; padding: 12px; border-radius: 18px; background: var(--surface); border: 1.5px solid var(--line); }
.m-row-open { display: flex; gap: 12px; flex: 1; min-width: 0; text-align: left; border-radius: 12px; }
.m-row-open:active .m-thumb { transform: scale(0.97); }
.m-thumb { position: relative; flex: none; width: 104px; height: 104px; border-radius: 14px; overflow: hidden; background: var(--sunken); transition: transform 0.18s ease; }
.m-thumb > img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
.m-thumb .m-tag { position: absolute; left: 6px; bottom: 6px; }
.m-nophoto { display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 4px; text-align: center; color: var(--ink-2); border: 1.5px dashed var(--ink-3); border-radius: 14px; background: var(--paper); padding: 8px; }
.m-nophoto .m-caption { font-weight: 700; }
.m-row-text { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 4px; padding-right: 44px; }
.m-row-name { font-size: calc(16px * var(--ts)); font-weight: 700; line-height: 1.25; overflow-wrap: anywhere; }
.m-row-desc { color: var(--ink-2); display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; }
.m-row-price { font-weight: 700; margin-top: auto; }
.m-row-compare { position: absolute; top: 10px; right: 10px; width: 40px; height: 40px; border-radius: 999px; display: inline-flex; align-items: center; justify-content: center; background: var(--sunken); color: var(--ink); }
.m-row-compare[aria-pressed="true"] { background: var(--ink); color: var(--paper); }

.m-photo-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 14px 10px; padding: 8px 16px 0; }

.m-comparebar { position: absolute; left: 14px; right: 14px; bottom: 22px; z-index: 30; display: flex; align-items: center; gap: 10px; padding: 8px 8px 8px 16px; border-radius: 999px; background: var(--ink); color: var(--paper); box-shadow: var(--shadow-float); }
.m-comparebar .m-btn { min-height: 44px; padding: 0 18px; flex: none; }

.m-strip { position: relative; height: 320px; background: var(--sunken); overflow: hidden; }
.m-strip > img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
.m-strip-nav { position: absolute; top: 50%; transform: translateY(-50%); }
.m-strip-foot { position: absolute; left: 14px; right: 14px; bottom: 12px; display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.m-dots { display: inline-flex; gap: 5px; align-items: center; }
.m-dots span { width: 6px; height: 6px; border-radius: 99px; background: rgba(255,255,255,0.55); }
.m-dots span[data-on="true"] { width: 18px; background: #fff; }
.m-hero-nophoto { height: 220px; margin: 0 16px; }

.m-facts { display: flex; flex-direction: column; gap: 10px; padding: 14px 16px 0; }
.m-fact { display: grid; grid-template-columns: 96px 1fr; gap: 12px; padding: 10px 0; border-top: 1px solid var(--line); }
.m-fact .k { color: var(--ink-3); font-size: calc(13px * var(--ts)); padding-top: 2px; }
.m-fact .v { font-weight: 600; }
.m-fact .v small { display: block; font-weight: 400; color: var(--ink-2); margin-top: 2px; font-size: calc(13px * var(--ts)); line-height: 1.35; }
.m-actions { display: flex; flex-direction: column; gap: 10px; padding: 18px 16px 28px; }

.m-compare-grid { display: grid; gap: 10px; padding: 12px 16px 0; align-items: start; }
.m-col { display: flex; flex-direction: column; gap: 8px; min-width: 0; padding: 10px; border-radius: 16px; background: var(--surface); border: 1.5px solid var(--line); }
.m-col .m-thumb { width: 100%; height: auto; aspect-ratio: 1; }
.m-col .m-nophoto { width: 100%; aspect-ratio: 1; }
.m-col-name { font-weight: 700; font-size: calc(14px * var(--ts)); line-height: 1.25; overflow-wrap: anywhere; }
.m-col .m-btn { min-height: 40px; padding: 0 14px; font-size: calc(13px * var(--ts)); }
.m-note { margin: 14px 16px 0; padding: 12px 14px; border-radius: 14px; background: var(--sunken); color: var(--ink-2); }

/* ---- home: restaurant cards and the picker ---- */
.m-rail { display: flex; gap: 10px; overflow-x: auto; padding: 8px 16px 4px; scrollbar-width: none; scroll-snap-type: x proximity; }
.m-rail::-webkit-scrollbar { display: none; }
.m-rail > div { flex: none; scroll-snap-align: start; }
.m-restcard { display: flex; flex-direction: column; width: 200px; border-radius: 18px; overflow: hidden; background: var(--surface); border: 1.5px solid var(--line); text-align: left; }
.m-restcard:active { transform: scale(0.985); }
.m-restcard[disabled] { opacity: 0.6; pointer-events: none; }
.m-restcard-strip { display: flex; gap: 2px; height: 92px; background: var(--sunken); }
.m-restcard-strip img { flex: 1; min-width: 0; height: 100%; object-fit: cover; }
.m-restcard-text { display: flex; flex-direction: column; gap: 2px; padding: 10px 12px 12px; min-width: 0; }
.m-pick-list { display: flex; flex-direction: column; gap: 10px; padding: 12px 16px 0; }
.m-pick { display: flex; align-items: center; gap: 12px; width: 100%; padding: 10px 12px 10px 10px; border-radius: 18px; background: var(--surface); border: 1.5px solid var(--line); text-align: left; }
.m-pick:active { transform: scale(0.985); }
.m-pick-strip { display: flex; gap: 2px; width: 108px; height: 72px; border-radius: 12px; overflow: hidden; background: var(--sunken); flex: none; }
.m-pick-strip img { flex: 1; min-width: 0; height: 100%; object-fit: cover; }
.m-pick-text { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 2px; }
.m-pick-none { padding: 10px 14px; background: transparent; }

/* ---- tab bar: labeled, on a surface dark enough for the inactive tabs to read ---- */
.morsel-app .m-tabbar { background: rgba(28, 18, 10, 0.86); border-color: rgba(255,255,255,0.12); padding: 5px; gap: 2px; }
.morsel-app .m-tab { position: relative; width: auto; min-width: 84px; height: 50px; padding: 0 12px; flex-direction: column; gap: 3px; color: rgba(255, 249, 240, 0.92); }
.morsel-app .m-tab[data-active="true"] { background: rgba(255, 249, 240, 0.96); color: #26190E; }
.m-tab-label { font-size: 11px; font-weight: 700; letter-spacing: 0.02em; line-height: 1; }
.m-tab-badge { position: absolute; top: 3px; right: 8px; min-width: 17px; height: 17px; border-radius: 999px; background: var(--accent); color: var(--accent-ink); font-size: 11px; font-weight: 800; display: inline-flex; align-items: center; justify-content: center; padding: 0 5px; }
/* the tab bar floats over reserved space, never over content */
.morsel-app[data-tabs="true"] .m-screen { padding-bottom: 92px; }
/* compare: three columns only while the text fits them; at large text, two then one */
.morsel-app[data-ts="large"] .m-compare-grid[data-n="3"] { grid-template-columns: 1fr 1fr !important; }
.morsel-app[data-ts="large"] .m-col .m-tag { font-size: 11px; }

/* ---- standalone phone viewports: the app fills the screen at native size ----
   Set by app.jsx when the page is top-level and narrower than 480px. Embedded and
   capture contexts keep the fixed 402px device, so figures and the case-study
   stage are unaffected. The status-bar clearances the device needed collapse. */
.morsel-app-shell[data-frame="none"] { display: block; width: 100%; }
.morsel-app-shell[data-frame="none"] > .morsel-app { height: 100vh; height: 100dvh; min-height: 520px; }
.morsel-app-shell[data-frame="none"] .m-topbar { padding-top: 14px !important; }
.morsel-app-shell[data-frame="none"] .m-home-head { padding-top: 20px !important; }
.morsel-app-shell[data-frame="none"] .m-hero-wrap { padding-top: 70px !important; }
.morsel-app-shell[data-frame="none"] .m-strip-back { top: 14px !important; }
.morsel-app-shell[data-frame="none"] .m-tabbar { bottom: 14px; }
.morsel-app-shell[data-frame="none"] .m-demo-controls { margin: 12px 16px 0 !important; }
html[data-morsel-frame="none"] .twk-panel { display: none; }

/* the dish page has no tab bar; its last button still clears the home indicator */
.morsel-app[data-tabs="false"] .m-actions { padding-bottom: 46px; }

/* Native phone comparison prioritizes readable columns over fitting all three abreast. */
@media (max-width: 479px) {
  .morsel-app-shell[data-frame="none"] .m-compare-grid[data-n="3"] { grid-template-columns: repeat(2, minmax(0, 1fr)) !important; }
}
.m-col { overflow-wrap: anywhere; }

