body{margin:0;background:#E9EAEB;color:#24282B;font-family:'Plus Jakarta Sans',sans-serif}a{color:#8C6A25}a:hover{color:#6E521C}
:root{--c-bg:#182430;--c-bd:#2A3B49;--c-a1:#DFB05C;--c-txt:#C9D3DB;--c-dim:#8FA3B3;--annD:block;--frameCols:1fr 300px 320px;--frameRows:300px 230px;--tickSpan:span 2}


button{font:inherit;color:inherit;background:none;border:none;padding:0;margin:0;text-align:inherit;cursor:pointer}
button:focus-visible,input:focus-visible,.ticket-details:focus-visible{outline:2px solid #B98A2B;outline-offset:2px}
.order-ticket{background:#F6F7F7;padding:14px 16px;display:flex;flex-direction:column;gap:8px;grid-row:var(--tickSpan);min-height:0;overflow:hidden;box-sizing:border-box}
.ticket-details{flex:1;min-height:0;overflow-y:auto;display:flex;flex-direction:column;gap:8px;padding:2px 3px 8px;scrollbar-gutter:stable}
.ticket-details>*{flex-shrink:0}
.ticket-summary{order:1;display:flex;flex-direction:column;gap:8px}
.ticket-actions{flex:none;display:flex;flex-direction:column;gap:8px;border-top:1px solid #D5DADD;padding-top:10px}
.ticket-action-group{display:flex;flex-direction:column;gap:8px;background:var(--c-bg);border:1px solid var(--c-bd);border-radius:12px;padding:10px}
.ticket-actions button{flex-shrink:0;min-height:44px;border-radius:8px;box-sizing:border-box}
.ticket-cancel{border:1px solid var(--c-dim);color:var(--c-txt);font:600 12px 'Plus Jakarta Sans';text-align:center;padding:8px}
.ticket-cancel:hover{background:rgba(255,255,255,.07)}

@media (prefers-reduced-motion:reduce){*,*::before,*::after{transition-duration:.01ms !important;animation-duration:.01ms !important}}
/* ?bare — the case-study embed shows the workstation, not the board around it */
:root[data-bare] [data-scaffold]{display:none !important}
:root[data-bare] body>div:first-child{padding-bottom:16px}
